"""Seven Days of Uncle Lee: match the case document (12 Nov 2026).
Ah-Mei is his wife (born 1981, from mainland China, shift worker at the Gangshan Veterans Home, home a few days a week,
a big age gap and some quarrels). The person he misses is his mother in Qingdao, left behind when he was conscripted
at 15 (1948); he went back in 1988, nine years too late. Xiulan is gone. The dog is called เจ้าดำ as in Case D."""
import sys
f = sys.argv[1]; s = open(f, encoding='utf-8').read()
def sub(old, new, n=1):
    global s
    assert s.count(old) == n, (old[:70], s.count(old)); s = s.replace(old, new)

# ---- day 1 ----
sub("""card('photo'); await say(first?['ซิ่วหลาน อายุยี่สิบสอง','วันนั้นเธอยืมรองเท้าพี่สาวมาใส่\\nคับไปครึ่งเบอร์ เธอยิ้มทั้งวันทั้งที่เจ็บเท้า','หกปีแล้ว\\nที่ผมเป็นคนเดียวในโลก ที่ยังรู้เรื่องรองเท้าคู่นั้น','อรุณสวัสดิ์']:['อรุณสวัสดิ์ ซิ่วหลาน']);""",
    """card('photo'); await say(first?['รูปแต่งงาน ปีสองพันห้า\\nผมเจ็ดสิบสอง อาเหมยยี่สิบสี่','คนในหมู่บ้านนินทาว่าเธอแต่งกับเงินบำนาญ\\nปีแรกๆ ผมเองก็แอบคิดแบบนั้น','จนปีที่ผมเป็นปอดบวม เธอนั่งเฝ้าที่โรงพยาบาลสามคืน\\nเงินบำนาญไม่เคยนั่งเฝ้าใคร','ผมไม่มีรูปแม่สักใบ\\nหน้าแม่ในหัวผม จางลงปีละนิด เหมือนรูปที่โดนแดด']:['สิบเจ็ดปีแล้ว\\nรูปนี้ซีดลงทุกปี แต่เธอยังโทรมาทุกเช้า']);""")
sub("'ปฏิทินปีก่อนๆ วงด้วยปากกาน้ำเงิน ลายมือซิ่วหลาน\\nเดือนละวงสองวง ตั้งแต่ปีที่เธอไป วงแดงของผมก็งอกขึ้นทุกปี'",
    "'มีวงสีน้ำเงินด้วย ลายมืออาเหมย\\nวันที่เธอได้กลับบ้าน สัปดาห์ละสองวง ผมนับวงน้ำเงินบ่อยกว่าวงแดง'")
sub("""card('slippers'); await say(first?['รองเท้าแตะคู่เล็กข้างประตู หันปลายเข้าห้อง\\nเธอถอดไว้แบบนี้ทุกครั้งที่กลับจากตลาด','หกปี ผมไม่เคยย้ายมัน\\nกวาดบ้านทีไร ผมกวาดอ้อม','ผ้ากันเปื้อนบนตะปู ยังมีรอยน้ำมันจุดหนึ่ง\\nจากกับข้าวมื้อสุดท้ายที่เธอทำ']:['ยังอยู่ที่เดิม']);""",
    """card('slippers'); await say(first?['รองเท้าแตะคู่เล็กข้างประตู หันปลายเข้าห้อง\\nของอาเหมย เธอถอดไว้แบบนี้ทุกครั้งที่กลับจากเวร','สัปดาห์หนึ่ง มันได้ใส่สองสามวัน\\nวันที่เหลือ มันรออยู่ตรงนี้ เหมือนผม','ผ้ากันเปื้อนบนตะปู ยังมีแป้งติดอยู่จุดหนึ่ง\\nจากเกี๊ยวที่เธอห่อเมื่อวันอาทิตย์']:['ยังรออยู่']);""")
sub("'อังคาร – เช้า เจ็ดเม็ด\\nผมไม่รู้ว่าเม็ดไหนรักษาอะไร สี่สิบปี ซิ่วหลานเป็นคนรู้แทนผม'",
    "'อังคาร – เช้า เจ็ดเม็ด\\nผมไม่รู้ว่าเม็ดไหนรักษาอะไร อาเหมยรู้แทนผม เธอจัดยาให้คนแก่ที่บ้านพักวันละสามสิบคน รวมผมเป็นสามสิบเอ็ด'")
sub("'กล่องยาเจ็ดช่อง เจ็ดวัน\\nอาเหมยจัดให้ทุกวันอาทิตย์ นิ้วเธอเร็วเหมือนคนนับธนบัตร'", "'กล่องยาเจ็ดช่อง เจ็ดวัน\\nอาเหมยจัดให้ทุกวันหยุดของเธอ นิ้วเธอเร็วเหมือนคนนับธนบัตร'")
sub("""await say(['อาเหมยอยู่ชั้นสอง ทำงานที่บ้านพักทหารผ่านศึก\\nเธอดูแลคนแก่ทั้งวัน แล้วยังเหลือแรงมาดูแลอีกคนหนึ่ง','เจ็ดโมงตรง เธอจะโทรมา\\n"ลุงหลี่ กินยาเช้าหรือยังคะ"',""",
    """await say(['อาเหมยเป็นภรรยาผม อายุสี่สิบเอ็ด\\nเธอทำงานเป็นกะที่บ้านพักทหารผ่านศึกกังซาน สัปดาห์หนึ่งได้กลับบ้านสองสามวัน','วันที่ไม่ได้กลับ เธอดูแลคนแก่ของคนอื่นทั้งวัน\\nแล้วโทรมาดูแลคนแก่ของตัวเอง เจ็ดโมงตรง','"เหล่าหลี่ กินยาเช้าหรือยังคะ"\\nเธอเรียกผมเหมือนเรียกเพื่อนรุ่นเดียวกัน ทั้งที่ผมแก่กว่าพ่อเธอ',""")
sub("""  await say(['…เพลงนี้','ซิ่วหลานเคยเต้นเพลงนี้ในครัว มือหนึ่งถือตะหลิว\\nน้ำมันกระเด็นใส่แขน เธอก็ไม่หยุด','เธอกวักมือเรียก\\nผมบอกว่า เข่าไม่ดี','ตอนนั้นผมอายุห้าสิบเอ็ด\\nเข่าผมไม่ได้เป็นอะไรเลย','เพลงนี้ยาวสามนาทีสิบวินาที\\nผมมีเวลาทั้งชีวิต แต่ไม่ได้ให้เธอสามนาทีนั้น']);""",
    """  await say(['…เพลงนี้','เพลงพื้นบ้านซานตง\\nแม่ร้องเพลงนี้ทุกตรุษจีน ผูกผ้าแดงที่เอว แล้วเต้นยางเกอในลานบ้านที่ชิงเต่า','ตรุษจีนปีหนึ่งเก้าสี่แปด แม่กวักมือเรียกผมเข้าไปเต้นด้วย\\nผมบอกว่า ผมโตแล้ว ไม่เต้นแบบเด็กๆ','ผมอายุสิบห้า\\nสามเดือนต่อมา ทหารมาที่หมู่บ้าน ผมได้โตจริงๆ ในวันเดียว','เพลงนี้ยาวสามนาทีสิบวินาที\\nผมมีเวลาทั้งชีวิต แต่ไม่ได้ให้แม่สามนาทีนั้น']);""")
sub("""  await say(['มื้อเย็น','ผมวางชามสองใบ ตะเกียบสองคู่\\nมือมันทำของมันเอง ก่อนที่หัวจะทันห้าม','หกปี สองพันกว่ามื้อ\\nมือผมยังไม่ได้รับแจ้งข่าว']);""",
    """  await say(['มื้อเย็น','ผมวางชามสองใบ ตะเกียบสองคู่\\nคืนนี้อาเหมยเข้าเวร ผมรู้ แต่มือก็วางไปแล้ว','ปีหนึ่งเก้าแปดแปด ผมได้กลับชิงเต่าครั้งแรก\\nช้าไปเก้าปี ชาวบ้านเล่าว่าแม่วางชามเผื่อผมทุกคืน สามสิบเอ็ดปี','ผมเลยวางเผื่อบ้าง\\nคนที่ยังกลับมาได้ ควรมีชามรออยู่']);""")
sub("await say(['ทุกคืน ผมรายงานซิ่วหลาน\\nเหมือนที่เคยรายงานผู้บังคับบัญชา']);",
    "await say(['ทุกคืน ผมเขียนรายงานถึงแม่ ลงสมุดเล่มเล็ก\\nเริ่มตอนอยู่ค่ายที่ไหหลำ จดหมายข้ามทะเลส่งไม่ได้ ผมเลยเขียนเก็บไว้','แม่อ่านหนังสือไม่ออก ไม่เคยได้อ่านสักฉบับ\\nทหารไม่หยุดรายงาน เพราะไม่มีคนอ่าน']);")
sub("'ราตรีสวัสดิ์ ซิ่วหลาน', 'อีกสามวัน", "'ราตรีสวัสดิ์ครับ แม่', 'อีกสามวัน")

# ---- day 2 ----
sub("มันรู้ตารางเวรของอาเหมยดีกว่าผม", "มันรู้ตารางเวรของอาเหมยดีกว่าผม เมื่อคืนเธอได้นอน วันนี้จะโทรมา")
sub("""  await say(['"ลุงหลี่ กินยาเช้าหรือยังคะ"']);
  const c=await choose""", """  await say(['"เหล่าหลี่ กินยาเช้าหรือยังคะ"']);
  const c=await choose""")
sub('\'"เมื่อวานหนูไม่ได้โทร ลุงไม่ลืมใช่ไหมคะ"\'', '\'"เมื่อวานหนูไม่ได้โทร ไม่ลืมใช่ไหมคะ"\'')
sub('"วันนี้ลุงจะไปไหนไหมคะ"\\n"ไปหาหมอ"', '"วันนี้จะไปไหนไหมคะ"\\n"ไปหาหมอ"')
sub("'เมื่อก่อน หมอถามอะไร ซิ่วหลานตอบแทนผมหมด\\nกินยาอะไร แพ้อะไร นอนกี่โมง ผมนั่งข้างเธอ พยักหน้าเป็นอย่างเดียว'",
    "'วันที่อาเหมยว่างไปด้วย หมอถามอะไร เธอตอบแทนผมหมด\\nกินยาอะไร แพ้อะไร นอนกี่โมง ผมนั่งข้างเธอ พยักหน้าเป็นอย่างเดียว วันนี้เธอไม่ว่าง'")
sub("""  await say(['ก้นลิ้นชัก มีซองยาเก่าอยู่ใบหนึ่ง กระดาษเหลือง มุมนุ่มเหมือนผ้า','ลายมือซิ่วหลาน ตัวโตเท่านิ้วโป้ง\\nพระอาทิตย์หนึ่งดวง พระจันทร์หนึ่งดวง จุดเม็ดยาวาดด้วยปากกา','เธอรู้ว่าตาผมไม่ดี ตั้งแต่ก่อนที่ผมจะยอมรับเอง','สิบสามซองนั้น ผมเก็บเป็นหลักฐาน\\nซองนี้ซองเดียว ที่ผมเก็บเพราะคิดถึง']);""",
    """  await say(['ก้นลิ้นชัก มีซองยาเก่าอยู่ใบหนึ่ง กระดาษเหลือง มุมนุ่มเหมือนผ้า','ลายมืออาเหมย ปีแรกที่แต่งงาน ตัวโตเท่านิ้วโป้ง\\nพระอาทิตย์หนึ่งดวง พระจันทร์หนึ่งดวง จุดเม็ดยาวาดด้วยปากกา','วันนั้นผมโกรธ หาว่าเธอดูถูกว่าผมอ่านหนังสือไม่ออก\\nเป็นครั้งแรกที่เราทะเลาะกัน เธอร้องไห้ ผมไม่ขอโทษ','ซองนั้นผมไม่ได้ทิ้ง\\nสิบสามซองนั้น ผมเก็บเป็นหลักฐาน ซองนี้ ผมเก็บเพราะยังไม่ได้ขอโทษ']);""")
sub("""  await show('dusk',3000); clock('17:30'); sfx.knock();
  await say(['ห้าโมงครึ่ง เสียงเคาะประตู สามครั้ง เบาๆ']); await show('amei',2000);
  await say(['อาเหมย กับกล่องเกี๊ยว','"หนูทำเยอะไปค่ะ"\\nเธอทำเยอะไปแบบนี้ทุกสัปดาห์ มาสามปีแล้ว','เธอเห็นสายจูงที่แขวนอยู่ข้างประตู\\nเธอมองเสี่ยวเฮย แล้วมองผม','"หนูพามันลงไปเดินให้นะคะ สิบนาที"']);
  const w=await choose([{t:'พยักหน้า'},{t:'"ไม่ต้องหรอก รบกวนเปล่าๆ"'}]);
  if(w===1) await say(['"ไม่รบกวนค่ะ หนูอยากเดินอยู่แล้ว"\\nเธอโกหกเก่งพอๆ กับผม']);""",
    """  await show('dusk',3000); clock('17:30'); sfx.knock();
  await say(['ห้าโมงครึ่ง เสียงไขกุญแจ\\nรองเท้าแตะคู่เล็กข้างประตู ได้เจ้าของคืนมาสองชั่วโมง ก่อนเธอกลับไปเข้าเวรดึก']); await show('amei',2000);
  await say(['อาเหมย กับกล่องเกี๊ยว','"หนูห่อเยอะไป"\\nเธอห่อเยอะไปแบบนี้ทุกครั้งที่กลับ เผื่อวันที่เธอไม่อยู่','เราเถียงกันเรื่องค่าไฟนิดหน่อย เธอว่าผมขี้เหนียวจนป่วย ผมว่าเธอใช้เงินแบบคนรุ่นใหม่\\nเราอายุห่างกันสี่สิบแปดปี บางวันมันห่างกว่านั้น','แล้วเธอก็เห็นสายจูงที่แขวนอยู่ข้างประตู\\nเธอมองเจ้าดำ แล้วมองผม','"หนูพามันลงไปเดินให้นะ สิบนาที"']);
  const w=await choose([{t:'พยักหน้า'},{t:'"ไม่ต้องหรอก เธอเพิ่งเลิกงาน"'}]);
  if(w===1) await say(['"ไม่เหนื่อยค่ะ หนูอยากเดินอยู่แล้ว"\\nเธอโกหกเก่งพอๆ กับผม']);""")
sub("'ของที่ไม่ได้รายงานอาเหมย: หนึ่งขวด','เสี่ยวเฮยได้ลงไปเดิน (ไม่ใช่กับผม)','เต้นรำ: ยังไม่ได้เต้น','ผู้มาเยี่ยม: อาเหมย สิบนาที'],'เหตุการณ์ทั่วไป: ปกติ','ราตรีสวัสดิ์ ซิ่วหลาน\\nวันนี้เป็นวันดี'",
    "'ของที่ไม่ได้รายงานอาเหมย: หนึ่งขวด','เสี่ยวเฮยได้ลงไปเดิน (ไม่ใช่กับผม)','เต้นรำ: ยังไม่ได้เต้น','อาเหมยกลับบ้าน: สองชั่วโมง เถียงกันหนึ่งเรื่อง'],'เหตุการณ์ทั่วไป: ปกติ','ราตรีสวัสดิ์ครับ แม่\\nวันนี้เป็นวันดี'")

