sub("""  await say(['"ลุงหลี่ กินยาเช้าหรือยังคะ"\\n"กำลังจะกิน คุณฟังนะ"']);""", """  await say(['"เหล่าหลี่ กินยาเช้าหรือยังคะ"\\n"กำลังจะกิน เธอฟังนะ"']);""")
sub("""'"วันนี้หนูหยุดค่ะ เย็นๆ จะแวะขึ้นไปนะคะ"'""", """'"เย็นนี้หนูกลับบ้านนะคะ อยู่ถึงวันอาทิตย์"'""")
sub("""'อาเหมยมาพร้อมเกี๊ยวอีกกล่อง\\n"ลุงเดินกะเผลกนะคะ"'""", """'อาเหมยกลับมาพร้อมเกี๊ยวอีกกล่อง\\n"เหล่าหลี่เดินกะเผลกนะ"'""")
sub('"ทำไมลุงไม่—"', '"ทำไมไม่—"')
sub("'อาเหมยมาพร้อมเกี๊ยวอีกกล่อง\\nเธอไม่ได้พูดเรื่องล้มอีก'", "'อาเหมยกลับมาพร้อมเกี๊ยวอีกกล่อง\\nเธอไม่ได้พูดเรื่องล้มอีก'")
sub("'ซิ่วหลาน ผมอยากรู้ว่าพรุ่งนี้จะเป็นยังไง\\nไม่ได้รู้สึกแบบนี้มานานแล้ว','พรุ่งนี้วันอาทิตย์ วันจัดยา', '', 'หม้อเล็กดีแล้ว\\nฉันบอกตั้งแต่ปีแรกที่แต่งงาน'",
    "'แม่ครับ ผมอยากรู้ว่าพรุ่งนี้จะเป็นยังไง\\nไม่ได้รู้สึกแบบนี้มานานแล้ว','พรุ่งนี้วันอาทิตย์ วันจัดยา', '', 'หม้อเล็กดีแล้ว\\nแม่บอกตั้งแต่เจ้ายังต้องเขย่งดูในหม้อ'")

# ---- day 6 ----
sub("""  await say(['"ลุงหลี่ กินยาเช้าหรือยังคะ"']); cardPic('pills_am'); await tapPills(5); cardPic('phone');
  await say(['ห้าเม็ด\\nเมื่อวานยังเจ็ด','"สิบโมงหนูขึ้นไปจัดยานะคะ"']); cardOff();
  clock('10:00'); await show('morning',2400); sfx.knock();
  await say(['วันอาทิตย์ อาเหมยมาจัดยาเหมือนทุกสัปดาห์']); card('fillbox');
  await say(['แต่วันนี้เธอไม่ได้จัดให้ เธอเลื่อนกล่องมาตรงหน้าผม\\n"ลุงจัดเองค่ะ หนูดูเฉยๆ ตามกระดาษที่น้องเภสัชแปะไว้"']);""",
    """  await say(['"เหล่าหลี่ กินยาเช้าหรือยังคะ"\\nเธอโทรจากตลาดข้างล่าง ทั้งที่อีกสิบนาทีก็ขึ้นมาถึง']); cardPic('pills_am'); await tapPills(5); cardPic('phone');
  await say(['ห้าเม็ด\\nเมื่อวานยังเจ็ด','"สิบโมงหนูจัดยาให้นะคะ"']); cardOff();
  clock('10:00'); await show('morning',2400);
  await say(['วันอาทิตย์ วันหยุดของอาเหมย วันจัดยา']); card('fillbox');
  await say(['แต่วันนี้เธอไม่ได้จัดให้ เธอเลื่อนกล่องมาตรงหน้าผม\\n"เหล่าหลี่จัดเองนะ หนูดูเฉยๆ ตามกระดาษที่น้องเภสัชแปะไว้"']);""")
sub("""'สี่สิบปี ซิ่วหลานจัดยาให้ผมทุกคืนวันอาทิตย์\\nหกปีต่อมาอาเหมยจัดแทน วันนี้เป็นครั้งแรกที่มือผมทำเอง','"พ่อหนูอยู่บ้านพักทหารผ่านศึก" เธอพูดขึ้นมาเฉยๆ ตามองกล่องยา\\n"ที่ที่หนูทำงานอยู่ตอนนี้แหละค่ะ"','"ตอนนั้นหนูทำงานอยู่ไทเป โทรหาพ่อเดือนละครั้ง\\nพ่อบอกว่า ปกติ ทุกครั้ง"','"หนูกลับมาไม่ทัน"\\nเธอปิดฝาช่องวันอาทิตย์ ดังแก๊ก','"หนูเลยโทรหาลุงทุกเช้า ลุงไม่ต้องขอบใจหนูหรอกค่ะ\\nหนูทำเพื่อตัวเอง"','ผมไม่รู้จะพูดอะไร\\nผมเลยสารภาพเรื่องกริ่งที่สอง','เธอหัวเราะจนน้ำตาไหล\\n"หนูนับกริ่งรอทุกวันค่ะ ลุง"','ซิ่วหลานก็เคยนับ\\nเธอโทรจากตลาดทุกเช้า ถามว่าเย็นนี้จะกินอะไร','ผมรับกริ่งที่สองทุกครั้ง เธอหัวเราะทุกครั้ง\\n"ทหารอะไร ยุ่งทุกเช้าตอนเจ็ดโมง"','หกปีมานี้ ผมยังรับกริ่งที่สอง\\nผมเพิ่งรู้วันนี้ ว่าผมรับให้เธอ'""",
    """'สิบเจ็ดปี อาเหมยจัดยาให้ผมทุกวันหยุดของเธอ\\nวันนี้เป็นครั้งแรกที่มือผมทำเอง ต่อหน้าเธอ','"พ่อหนูอยู่บ้านที่เหอหนาน" เธอพูดขึ้นมาเฉยๆ ตามองกล่องยา\\n"ตอนหนูมาทำงานที่นี่ หนูโทรกลับบ้านเดือนละครั้ง พ่อบอกว่า ปกติ ทุกครั้ง"','"หนูกลับไปไม่ทัน"\\nเธอปิดฝาช่องวันอาทิตย์ ดังแก๊ก','"หนูเลยโทรหาเหล่าหลี่ทุกเช้า ไม่ต้องขอบใจหนูหรอก\\nหนูทำเพื่อตัวเอง"','กลับไปไม่ทัน\\nสิบเจ็ดปี ผมไม่รู้เลยว่าเราสองคนแบกของชิ้นเดียวกันมา','ผมไม่รู้จะพูดอะไร\\nผมเลยสารภาพเรื่องกริ่งที่สอง','เธอหัวเราะจนน้ำตาไหล\\n"หนูนับกริ่งรอทุกวัน ถ้ากริ่งที่สองยังเงียบ หนูจะเริ่มกลัว"','ผมนึกว่ากริ่งที่สองเป็นเรื่องของผมคนเดียว\\nมันเป็นเรื่องของเราสองคนมาตลอด'""")
sub("""'"ลุงไม่ต้องเก็บซองยาไว้หรอกค่ะ" เธอพูดเหมือนรู้\\n"หนูถามลุงทุกวันอยู่แล้ว"'""", """'"ไม่ต้องเก็บซองยาไว้หรอก" เธอพูดเหมือนรู้\\n"หนูถามเหล่าหลี่ทุกวันอยู่แล้ว"'""")
sub("""'สี่โมงเย็น อาเหมยยังอยู่\\n"เพลงของใครคะ"','"ของซิ่วหลาน"\\nผมเล่าเรื่องตะหลิว เรื่องเข่า เรื่องอายุห้าสิบเอ็ด','หกปี ผมไม่เคยเล่าเรื่องนี้ให้ใครฟัง\\nพอเล่าแล้วมันเบาลง เหมือนลิ้นชัก'""",
    """'สี่โมงเย็น อาเหมยยังอยู่\\n"เพลงอะไรคะ"','"เพลงของแม่"\\nผมเล่าเรื่องลานบ้านที่ชิงเต่า เรื่องผ้าแดง เรื่องที่ผมบอกแม่ว่าผมโตแล้ว','สิบเจ็ดปี ผมไม่เคยเล่าให้เธอฟัง\\nเธอฟังจนจบ แล้วบอกว่า "แม่หนูก็เต้นยางเกอ ที่เหอหนานก็เต้น"','พอเล่าแล้วมันเบาลง\\nเหมือนลิ้นชัก'""")
sub("""  card('slippers'); await say(['อาเหมยกลับลงไปแล้ว\\nผมยืนมองรองเท้าคู่เล็กข้างประตูอยู่นาน']);
  const sl=await choose([{t:'เก็บใส่กล่อง วางไว้ข้างรูปแต่งงาน'},{t:'วางไว้ที่เดิม'}]); S.slip=sl===0?'box':'keep';
  await say(sl===0?['ผมเช็ดฝุ่นออก ห่อด้วยผ้ากันเปื้อนของเธอ\\nวางไว้บนชั้น ข้างรูปแต่งงาน','ไม่ได้ทิ้ง\\nแค่ย้ายจากทางที่ผมต้องเดินอ้อม มาไว้ในที่ที่ผมจะเห็นทุกวัน']:['ผมเช็ดฝุ่นออก แล้ววางไว้ที่เดิม\\nหันปลายเข้าห้อง เหมือนที่เธอวาง','บางอย่างไม่ต้องย้ายก็ได้\\nแต่ต่อจากนี้ ผมจะไม่กวาดอ้อมมันแล้ว']); cardOff();
""", "")
sub("""  await say(['คืนนี้ผมวางชามสองใบ\\nอีกใบของอาเหมย เธออยู่กินข้าวเย็นด้วย','มือผมวางถูกแล้ว เป็นครั้งแรกในรอบหกปี']);
  cardOff();""",
    """  await say(['คืนนี้ชามใบที่สองมีเจ้าของ\\nอาเหมยอยู่กินข้าวเย็นด้วย ก่อนกลับไปเข้าเวรดึก','กินเสร็จ ผมหยิบสมุดเล่มเล็กออกมา เหมือนทุกคืน\\n"เขียนอะไรทุกคืนคะ สิบเจ็ดปีแล้ว หนูไม่เคยถาม"']);
  const bk=await choose([{t:'ยื่นสมุดให้เธออ่าน'},{t:'"รายงานน่ะ ไม่มีอะไร"'}]); S.book=bk===0?'read':'keep';
  await say(bk===0?['เธอเปิดอ่านทีละหน้า ช้าๆ\\nรายงานถึงแม่ เจ็ดสิบสี่ปี สมุดสิบเก้าเล่ม เล่มนี้เล่มล่าสุด','เธอไม่ได้พูดอะไร\\nเธอหยิบปากกาของผม แล้วเขียนอะไรบางอย่างต่อท้ายหน้าของวันนี้','"ห้ามแอบอ่านก่อนนอนนะ" เธอว่า\\nทหารแก่ทำตามคำสั่ง']:['เธอพยักหน้า ไม่ถามต่อ\\nเธอเก็บชาม ล้างตะเกียบสองคู่ วางคว่ำไว้คู่กัน','สมุดเล่มนี้ ผมยังไม่พร้อม\\nแต่ผมรู้แล้วว่าวันหนึ่ง ผมจะยื่นให้เธอ']);
  cardOff();""")
sub("'เต้นรำ: เก็บแรงไว้ พรุ่งนี้','รองเท้าของซิ่วหลาน: '+(S.slip==='box'?'ย้ายไปไว้ข้างรูป':'อยู่ที่เดิม ฝุ่นออกแล้ว')],'เหตุการณ์ทั่วไป: ดีขึ้น','ซิ่วหลาน พรุ่งนี้ผมมีนัด\\nข้างล่าง','พรุ่งนี้ วันที่เจ็ด', '', S.slip==='box'?'ขอบใจที่เก็บไว้ใกล้ๆ\\nขอบใจอาเหมยแทนฉันด้วยนะ':'ไม่ต้องกวาดอ้อมแล้วนะ\\nขอบใจอาเหมยแทนฉันด้วย'",
    "'เต้นรำ: เก็บแรงไว้ พรุ่งนี้','สมุดเล่มนี้: '+(S.book==='read'?'มีคนอ่านแล้วหนึ่งคน':'ยังเป็นความลับ อีกไม่นาน')],'เหตุการณ์ทั่วไป: ดีขึ้น','แม่ครับ พรุ่งนี้ผมมีนัด\\nข้างล่าง','พรุ่งนี้ วันที่เจ็ด', '', S.book==='read'?'แม่คะ หนูชื่อเหมย\\nวันนี้เขาจัดยาเองได้แล้ว แม่ไม่ต้องห่วงนะคะ':'เมียเจ้าดีนะ\\nขอบใจเธอแทนแม่ด้วย'")

